/**
 * Better Auth-owned tables (user, session, account, verification, twoFactor,
 * passkey).
 *
 * These are MANAGED BY BETTER AUTH (spec 1: "Two table families") — the SQL
 * lives in packages/db/drizzle/0002_better_auth_tables.sql and
 * 0030_passkey.sql, generated by
 * Better Auth's own migration compiler (apps/server/scripts/gen-better-auth-sql.ts).
 * They are declared here ONLY so app code can query them with drizzle's typed
 * API (joins to employees, auth_events lookups, session idle enforcement).
 *
 * IMPORTANT: this file is deliberately NOT included in drizzle.config.ts
 * `schema`, so `drizzle-kit generate` never emits DDL for these tables.
 * Column definitions must mirror the generated SQL exactly (Better Auth uses
 * camelCase column names).
 */

import {
  boolean,
  index,
  integer,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
} from "drizzle-orm/pg-core";

export const authUser = pgTable("user", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  email: text("email").notNull().unique(),
  emailVerified: boolean("emailVerified").notNull(),
  image: text("image"),
  createdAt: timestamp("createdAt", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updatedAt", { withTimezone: true }).notNull().defaultNow(),
  // twoFactor() plugin
  twoFactorEnabled: boolean("twoFactorEnabled"),
  // admin() plugin
  role: text("role"),
  banned: boolean("banned"),
  banReason: text("banReason"),
  banExpires: timestamp("banExpires", { withTimezone: true }),
});

export const authSession = pgTable(
  "session",
  {
    id: text("id").primaryKey(),
    expiresAt: timestamp("expiresAt", { withTimezone: true }).notNull(),
    token: text("token").notNull().unique(),
    createdAt: timestamp("createdAt", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updatedAt", { withTimezone: true }).notNull().defaultNow(),
    ipAddress: text("ipAddress"),
    userAgent: text("userAgent"),
    userId: text("userId")
      .notNull()
      .references(() => authUser.id, { onDelete: "cascade" }),
    // admin() plugin (impersonation paths are disabled at code level)
    impersonatedBy: text("impersonatedBy"),
    // PAY-259: sign-in method (auth/session-method.ts); guards allowlist.
    authMethod: text("authMethod"),
  },
  (t) => [index("session_userId_idx").on(t.userId)],
);

export const authAccount = pgTable(
  "account",
  {
    id: text("id").primaryKey(),
    accountId: text("accountId").notNull(),
    providerId: text("providerId").notNull(),
    userId: text("userId")
      .notNull()
      .references(() => authUser.id, { onDelete: "cascade" }),
    accessToken: text("accessToken"),
    refreshToken: text("refreshToken"),
    idToken: text("idToken"),
    accessTokenExpiresAt: timestamp("accessTokenExpiresAt", { withTimezone: true }),
    refreshTokenExpiresAt: timestamp("refreshTokenExpiresAt", { withTimezone: true }),
    scope: text("scope"),
    password: text("password"),
    createdAt: timestamp("createdAt", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updatedAt", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("account_userId_idx").on(t.userId)],
);

export const authVerification = pgTable(
  "verification",
  {
    id: text("id").primaryKey(),
    identifier: text("identifier").notNull(),
    value: text("value").notNull(),
    expiresAt: timestamp("expiresAt", { withTimezone: true }).notNull(),
    createdAt: timestamp("createdAt", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updatedAt", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("verification_identifier_idx").on(t.identifier)],
);

export const authTwoFactor = pgTable("twoFactor", {
  id: text("id").primaryKey(),
  secret: text("secret").notNull(),
  /** Our JSON array of SHA-256 backup-code hashes (spec: hashed at rest). */
  backupCodes: text("backupCodes").notNull(),
  userId: text("userId")
    .notNull()
    .references(() => authUser.id, { onDelete: "cascade" }),
  verified: boolean("verified"),
  failedVerificationCount: integer("failedVerificationCount"),
  lockedUntil: timestamp("lockedUntil", { withTimezone: true }),
});

/**
 * passkey() plugin (PAY-259, migration 0030). The credentialID index is
 * UNIQUE by a deliberate hand edit (generated: plain index), so one
 * credential can never belong to two users.
 */
export const authPasskey = pgTable(
  "passkey",
  {
    id: text("id").primaryKey(),
    name: text("name"),
    publicKey: text("publicKey").notNull(),
    userId: text("userId")
      .notNull()
      .references(() => authUser.id, { onDelete: "cascade" }),
    credentialID: text("credentialID").notNull(),
    counter: integer("counter").notNull(),
    deviceType: text("deviceType").notNull(),
    backedUp: boolean("backedUp").notNull(),
    transports: text("transports"),
    createdAt: timestamp("createdAt", { withTimezone: true }),
    aaguid: text("aaguid"),
  },
  (t) => [
    index("passkey_userId_idx").on(t.userId),
    uniqueIndex("passkey_credentialID_idx").on(t.credentialID),
  ],
);
